package com.djibtout.backend.entity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="seller_documents") public class SellerDocument{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private SellerStore store;private String documentType,fileName,contentType;@Lob @Column(nullable=false)private byte[] content;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public SellerStore getStore(){return store;}public void setStore(SellerStore v){store=v;}public String getDocumentType(){return documentType;}public void setDocumentType(String v){documentType=v;}public String getFileName(){return fileName;}public void setFileName(String v){fileName=v;}public String getContentType(){return contentType;}public void setContentType(String v){contentType=v;}public byte[] getContent(){return content;}public void setContent(byte[]v){content=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
